package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.jobs.WorkerRecoveryTelemetry.*;
import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.springframework.transaction.support.TransactionSynchronizationManager;
class WorkerRecoveryMonitorTest {
 static final Clock CLOCK=Clock.fixed(Instant.parse("2026-01-01T00:00:00.123456789Z"),ZoneOffset.UTC);
 @AfterEach void clear(){TransactionSynchronizationManager.clear();Thread.interrupted();}
 @Test void constructorAndReadHaveNoScanOrSyntheticInitialEvidence(){var sweep=mock(WorkerRecoverySweep.class);var reads=new AtomicInteger();var value=new WorkerRecoveryMonitor(sweep,()->{reads.incrementAndGet();return new Snapshot(0,0,true);},CLOCK);assertNull(value.read());assertEquals(0,reads.get());verifyNoInteractions(sweep);}
 @Test void actualSuccessAndConsecutiveFailuresPreserveTheirDifferentMeaning(){var sweep=mock(WorkerRecoverySweep.class);when(sweep.scan()).thenReturn(new WorkerRecoverySweep.Result(1,0,0,1,false),new WorkerRecoverySweep.Result(1,0,0,1,false),new WorkerRecoverySweep.Result(1,1,0,0,false));var actual=new java.util.concurrent.atomic.AtomicReference<>(new Snapshot(100,1,false));var value=new WorkerRecoveryMonitor(sweep,actual::get,CLOCK);value.scan();assertEquals(1,value.read().consecutiveFailedScans());assertFalse(value.read().scanSuccessful());value.scan();assertEquals(2,value.read().consecutiveFailedScans());actual.set(new Snapshot(0,0,true));assertEquals(1,value.scan().recovered());assertTrue(value.read().scanSuccessful());assertEquals(0,value.read().consecutiveFailedScans());assertEquals(Instant.parse("2026-01-01T00:00:00.123456Z"),value.read().receivedAt());}
 @Test void partialFailedProofAndThrownScanRemoveEarlierEvidence(){var sweep=mock(WorkerRecoverySweep.class);when(sweep.scan()).thenReturn(new WorkerRecoverySweep.Result(0,0,0,0,false),new WorkerRecoverySweep.Result(200,0,200,0,true)).thenThrow(new IllegalStateException("fictional unavailable"));var value=new WorkerRecoveryMonitor(sweep,()->new Snapshot(0,0,true),CLOCK);value.scan();assertNotNull(value.read());assertThrows(RuntimeException.class,value::scan);assertNull(value.read());assertThrows(RuntimeException.class,value::scan);assertNull(value.read());}
 @Test void nativeSnapshotFailureOrTransactionNeverCreatesFreshHealthyFact(){var sweep=mock(WorkerRecoverySweep.class);when(sweep.scan()).thenReturn(new WorkerRecoverySweep.Result(0,0,0,0,false));var value=new WorkerRecoveryMonitor(sweep,()->{throw new IllegalStateException("fictional native proof unavailable");},CLOCK);assertThrows(RuntimeException.class,value::scan);assertNull(value.read());reset(sweep);TransactionSynchronizationManager.setActualTransactionActive(true);assertThrows(RuntimeException.class,value::scan);verifyNoInteractions(sweep);}
 @Test void overlappingScanCannotReplaceAnInflightOriginal()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var sweep=mock(WorkerRecoverySweep.class);when(sweep.scan()).thenAnswer(c->{entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));return new WorkerRecoverySweep.Result(0,0,0,0,false);});var value=new WorkerRecoveryMonitor(sweep,()->new Snapshot(0,0,true),CLOCK);var executor=Executors.newSingleThreadExecutor();try{var first=executor.submit(value::scan);assertTrue(entered.await(5,TimeUnit.SECONDS));assertNull(value.read());assertThrows(RuntimeException.class,value::scan);release.countDown();assertEquals(0,first.get(5,TimeUnit.SECONDS).failed());verify(sweep,times(1)).scan();}finally{release.countDown();executor.shutdownNow();}}
}
